import numpy as np

def annualise(sd, periods_per_year):
    return sd * np.sqrt(periods_per_year)

def realised_vol(r, window, annualise_it=True, zero_mean=False):
    x = np.asarray(r, dtype=float)[-window:]
    if zero_mean:
        sd = np.sqrt(np.mean(x ** 2))
    else:
        sd = np.std(x, ddof=1)
    return float(annualise(sd, 252)) if annualise_it else float(sd)

