import numpy as np
import pandas as pd

def best_window(r, true_var, windows):
    true_var = np.asarray(true_var, dtype=float)
    start = max(windows)
    errors = {}
    for w in windows:
        est = pd.Series(r, dtype=float).rolling(w).var().shift(1).to_numpy()
        errors[w] = np.mean((est[start:] - true_var[start:]) ** 2)
    return min(windows, key=lambda w: errors[w])
